<?php
namespace App\Http\Controllers\Webhook;
use App\Http\Controllers\Controller;
use App\Models\{Order,Payment,PaymentWebhook};
use Illuminate\Http\{JsonResponse,Request};
use Illuminate\Support\Facades\DB;
class MidtransWebhookController extends Controller {public function handle(Request $request):JsonResponse{$p=$request->all();$id=(string)($p['order_id']??'');$code=(string)($p['status_code']??'');$gross=(string)($p['gross_amount']??'');$sig=(string)($p['signature_key']??'');abort_if($id===''||$code===''||$gross===''||$sig==='',422);abort_unless(hash_equals(hash('sha512',$id.$code.$gross.config('midtrans.server_key')),$sig),403);$payment=Payment::where('payment_number',$id)->firstOrFail();$status=(string)($p['transaction_status']??'');$fraud=isset($p['fraud_status'])?strtolower((string)$p['fraud_status']):null;$event=PaymentWebhook::firstOrCreate(['provider'=>'midtrans','event_id'=>(string)($p['transaction_id']??$id).'-'.$status],['payment_id'=>$payment->id,'event_type'=>$status,'payload'=>$p]);if($event->is_processed)return response()->json(['message'=>'Already processed.']);DB::transaction(function()use($payment,$p,$status,$fraud,$event){$pay=Payment::lockForUpdate()->findOrFail($payment->id);$success=in_array($status,['settlement','capture'],true)&&($status!=='capture'||$fraud===null||$fraud==='accept');if($success){$pay->update(['provider_transaction_id'=>$p['transaction_id']??null,'payment_method'=>$p['payment_type']??null,'status'=>Payment::STATUS_PAID,'fraud_status'=>$fraud,'paid_at'=>now(),'provider_response'=>$p]);$pay->order()->update(['payment_status'=>Order::PAYMENT_PAID,'status'=>Order::STATUS_CONFIRMED,'confirmed_at'=>now()]);}elseif($status==='expire'&&$pay->status!==Payment::STATUS_PAID){$pay->update(['status'=>Payment::STATUS_EXPIRED,'provider_response'=>$p]);$pay->order()->update(['payment_status'=>Order::PAYMENT_FAILED]);}elseif(in_array($status,['cancel','deny','failure'],true)&&$pay->status!==Payment::STATUS_PAID){$pay->update(['status'=>Payment::STATUS_FAILED,'failed_at'=>now(),'provider_response'=>$p]);$pay->order()->update(['payment_status'=>Order::PAYMENT_FAILED]);}elseif(in_array($status,['refund','partial_refund'],true)){$pay->update(['status'=>Payment::STATUS_REFUNDED,'refunded_at'=>now(),'provider_response'=>$p]);$pay->order()->update(['payment_status'=>Order::PAYMENT_REFUNDED]);}else{$pay->update(['provider_response'=>$p]);}$event->update(['payload'=>$p,'is_processed'=>true,'processing_message'=>'Processed','processed_at'=>now()]);});return response()->json(['message'=>'Processed.']);}}
